3: export function validateGraph(graph, objective) {
4:   if (!graph || graph.objective !== objective || !nonempty(graph.summary)
5:     || !Array.isArray(graph.nodes) || graph.nodes.length < 1 || graph.nodes.length > 8) {
6:     throw new Error('Expected the original objective, a research summary, and 1–8 nodes.');
7:   }
8:   const nodes = new Map();
9:   for (const node of graph.nodes) {
10:     if (!node || typeof node.id !== 'string' || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(node.id)
11:       || !nonempty(node.title) || !nonempty(node.reason)
12:       || !Array.isArray(node.evidence) || !node.evidence.length || !node.evidence.every(nonempty)
13:       || !Array.isArray(node.dependsOn) || !node.dependsOn.every(nonempty) || nodes.has(node.id)) {
14:       throw new Error('Each node needs a unique slug id, title, reason, evidence, and dependsOn array.');
15:     }
16:     // Outcomes are absent from a freshly planned graph and appended later by `tag record`.
17:     if (node.outcomes !== undefined && (!Array.isArray(node.outcomes) || !node.outcomes.length
18:       || !node.outcomes.every(item => item && nonempty(item.at) && nonempty(item.outcome)))) {
19:       throw new Error(`Node ${node.id} has outcomes that are not a nonempty list of {at, outcome}.`);
20:     }
21:     nodes.set(node.id, node);
22:   }
23:   const visiting = new Set();
24:   const visited = new Set();
25:   function visit(id) {
26:     if (!nodes.has(id)) throw new Error(`Unknown dependency: ${id}`);
27:     if (visiting.has(id)) throw new Error(`Dependency cycle: ${id}`);
28:     if (visited.has(id)) return;
29:     visiting.add(id);
30:     for (const dependency of nodes.get(id).dependsOn) visit(dependency);
31:     visiting.delete(id);
32:     visited.add(id);
33:   }
34:   for (const id of nodes.keys()) visit(id);
35:   return graph;
36: }
