38: async function request(path, options, fetchImpl) {
39:   let response;
40:   try {
41:     response = await fetchImpl(`${API}${path}`, { ...options, signal: AbortSignal.timeout(120_000) });
42:   } catch (error) {
43:     throw new Error(`OpenRouter unavailable (${error.cause?.code ?? error.name}). No retry was made.`);
44:   }
45:   if (!response.ok) throw new Error(`OpenRouter HTTP ${response.status}. No retry was made.`);
