49: export async function plan(objective, directory, {
50:   apiKey = process.env.OPENROUTER_API_KEY,
51:   fetchImpl = fetch,
52: } = {}) {
53:   if (typeof objective !== 'string' || !objective.trim()) throw new Error('An objective is required.');
54:   if (!apiKey) throw new Error('Set OPENROUTER_API_KEY before planning.');
55:   const investigate = await repositoryTools(directory);
56:   const output = join(directory, '.tag');
57:   try {
58:     await mkdir(output, { mode: 0o700 });
59:   } catch (error) {
60:     if (error.code === 'EEXIST') throw new Error('.tag already exists. Preserve or move it before starting another experiment.');
61:     throw error;
62:   }
63:   await writeFile(join(output, '.gitignore'), '*\n', { flag: 'wx', mode: 0o600 });
64:   // A failed run is an experimental result: keep what it did and what it answered.
65:   const attempt = { model: MODEL, createdAt: new Date().toISOString(), requests: 0, costUsd: 0, investigation: [] };
66:   let keep = false;
67:   try {
68:     const { data } = await request('/models', {}, fetchImpl);
69:     const model = data?.find(item => item.id === MODEL);
70:     const promptPrice = Number(model?.pricing?.prompt);
71:     const completionPrice = Number(model?.pricing?.completion);
72:     // Deliberately conservative caps, not a general-purpose cost reservation system.
73:     if (!model || !Number.isFinite(promptPrice) || promptPrice < 0 || promptPrice > 0.5 / 1e6
74:       || !Number.isFinite(completionPrice) || completionPrice < 0 || completionPrice > 1.5 / 1e6
75:       || Number(model.pricing.request ?? 0) !== 0) {
76:       throw new Error('Model unavailable or pricing exceeds the seed’s budget caps. Human review required.');
77:     }
78:     const messages = [
79:       { role: 'system', content: instructions },
80:       { role: 'user', content: objective },
81:     ];
82:     const investigation = attempt.investigation;
83:     for (let turn = 1; turn <= MAX_REQUESTS; turn++) {
84:       attempt.requests = turn;
85:       const body = {
86:         model: MODEL, messages, tools, max_tokens: MAX_OUTPUT,
87:         tool_choice: turn === MAX_REQUESTS ? 'none' : 'auto',
88:         temperature: 0.2,
89:         provider: { max_price: { prompt: 0.5, completion: 1.5 } },
90:       };
91:       if (Buffer.byteLength(JSON.stringify(body)) > MAX_CONTEXT_BYTES) {
92:         throw new Error('Research context limit reached. No graph saved; human review required.');
93:       }
94:       const response = await request('/chat/completions', {
95:         method: 'POST',
96:         headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' },
97:         body: JSON.stringify(body),
98:       }, fetchImpl);
99:       const cost = response.usage?.cost;
100:       attempt.costUsd = attempt.costUsd !== null && typeof cost === 'number' && Number.isFinite(cost) && cost >= 0
101:         ? attempt.costUsd + cost : null;
102:       const choice = response.choices?.[0];
103:       const message = choice?.message;
104:       if (!message || choice.finish_reason === 'length' || response.error) {
105:         throw new Error('The model returned an error or incomplete answer. No retry was made.');
106:       }
107:       if (message.tool_calls?.length) {
108:         if (turn === MAX_REQUESTS || message.tool_calls.length > 12) throw new Error('Investigation limit reached.');
109:         messages.push({ role: 'assistant', content: message.content ?? null, tool_calls: message.tool_calls });
110:         for (const call of message.tool_calls) {
111:           let args;
112:           let result;
113:           try {
114:             args = JSON.parse(call.function.arguments);
115:             result = await investigate(call.function.name, args);
116:           } catch {
117:             // Do not return raw filesystem errors or other environment details to the model.
118:             result = 'Tool unavailable or invalid arguments. Use listed tracked text files and the documented tool parameters.';
119:           }
120:           investigation.push({ tool: call.function.name, arguments: args ?? {}, result });
121:           messages.push({ role: 'tool', tool_call_id: call.id, content: result });
122:         }
123:         continue;
124:       }
125:       if (!investigation.some(item => item.tool === 'read_file' && /^\d+: /.test(item.result))) {
126:         throw new Error('The model proposed a graph without reading repository evidence.');
127:       }
128:       attempt.answer = message.content;
129:       // A complete, otherwise valid graph was once discarded because the model wrapped it in a
130:       // markdown fence. Removing that envelope is not JSON repair: malformed JSON inside it,
131:       // a drifted objective or an invalid graph are still rejected exactly as before.
132:       const fenced = message.content.trim().match(/^```[a-z]*\s*\n([\s\S]*?)\n?```$/i);
133:       let graph;
134:       try {
135:         graph = validateGraph(JSON.parse(fenced ? fenced[1] : message.content), objective);
136:       } catch (error) {
137:         throw new Error(`Invalid planner graph: ${error.message}. No repair or retry was made.`);
138:       }
139:       graph.run = { model: MODEL, createdAt: attempt.createdAt, requests: turn, costUsd: attempt.costUsd, investigation };
140:       const html = renderGraph(graph);
141:       keep = true;
142:       await writeFile(join(output, 'graph.json'), JSON.stringify(graph, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
143:       await writeFile(join(output, 'graph.html'), html, { flag: 'wx', mode: 0o600 });
144:       return join(output, 'graph.html');
145:     }
146:     throw new Error('Investigation limit reached. No graph saved.');
147:   } catch (error) {
148:     if (!attempt.investigation.length && attempt.answer === undefined) throw error;
149:     // Without this the run's transcript and rejected answer are lost and the failure cannot be diagnosed.
150:     const record = { objective, failure: error.message, run: attempt };
151:     try {
152:       await writeFile(join(output, 'failed-run.json'), JSON.stringify(record, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
153:       keep = true;
154:       throw new Error(`${error.message} The attempt is preserved in .tag/failed-run.json; inspect and move it aside before running again.`);
155:     } catch (writeError) {
156:       throw writeError.message.includes(error.message) ? writeError : error;
157:     }
158:   } finally {
159:     if (!keep) await rm(output, { recursive: true });
160:   }
161: }
